import { defineUserSignupFields } from 'wasp/server/auth'

export const userSignupFields = defineUserSignupFields({
  username: (data: any) => {
    if (!data || !data.username) {
      throw new Error('Username is required')
    }
    if (typeof data.username !== 'string') {
      throw new Error('Username must be a string')
    }
    return data.username
  },
})

import { HttpError } from 'wasp/server'

export const getDocuments = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: userId },
        {
          permissions: {
            some: {
              userId: userId,
            },
          },
        },
      ],
    },
    orderBy: {
      updatedAt: 'desc',
    },
  })
}

export const getDocument = async (args: { id: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id
  const docId = Number(args.id)

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
    include: {
      owner: true,
      versions: {
        include: {
          author: true,
        },
        orderBy: {
          createdAt: 'asc',
        },
      },
      permissions: {
        include: {
          user: true,
        },
      },
    },
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  const isOwner = document.ownerId === userId
  const hasPermission = document.permissions.some((p: any) => p.userId === userId)

  if (!isOwner && !hasPermission) {
    throw new HttpError(403, 'Access Denied')
  }

  let role = 'VIEW'
  if (isOwner) {
    role = 'OWNER'
  } else {
    const perm = document.permissions.find((p: any) => p.userId === userId)
    if (perm) {
      role = perm.role
    }
  }

  return {
    ...document,
    userRole: role,
  }
}

export const getPermissions = async (args: { documentId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id
  const docId = Number(args.documentId)

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  if (document.ownerId !== userId) {
    throw new HttpError(403, 'Access Denied')
  }

  return context.entities.Permission.findMany({
    where: { documentId: docId },
    include: {
      user: true,
    },
  })
}

import { HttpError } from 'wasp/server'
import { ioInstance } from './webSocket'

export const createDocument = async (args: { title: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }
  if (!args.title || args.title.trim() === '') {
    throw new HttpError(400, 'Title is required')
  }

  return context.entities.Document.create({
    data: {
      title: args.title.trim(),
      content: '',
      ownerId: context.user.id,
    },
  })
}

export const updateDocumentContent = async (args: { id: number, content: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id
  const docId = Number(args.id)

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
    include: {
      permissions: true,
    },
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  const isOwner = document.ownerId === userId
  const hasEditPermission = document.permissions.some((p: any) => p.userId === userId && p.role === 'EDIT')

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, 'Access Denied')
  }

  const updatedDoc = await context.entities.Document.update({
    where: { id: docId },
    data: {
      content: args.content,
    },
  })

  if (ioInstance) {
    const roomId = `document-${docId}`
    ioInstance.to(roomId).emit('documentEdit', { content: args.content })
  }

  return updatedDoc
}

export const saveVersion = async (args: { documentId: number, content: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id
  const docId = Number(args.documentId)

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
    include: {
      permissions: true,
    },
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  const isOwner = document.ownerId === userId
  const hasEditPermission = document.permissions.some((p: any) => p.userId === userId && p.role === 'EDIT')

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, 'Access Denied')
  }

  const version = await context.entities.Version.create({
    data: {
      documentId: docId,
      content: args.content,
      authorId: userId,
    },
  })

  await context.entities.Document.update({
    where: { id: docId },
    data: {
      content: args.content,
    },
  })

  if (ioInstance) {
    const roomId = `document-${docId}`
    ioInstance.to(roomId).emit('documentEdit', { content: args.content })
  }

  return version
}

export const restoreVersion = async (args: { documentId: number, versionId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id
  const docId = Number(args.documentId)
  const versionId = Number(args.versionId)

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
    include: {
      permissions: true,
    },
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  const isOwner = document.ownerId === userId
  const hasEditPermission = document.permissions.some((p: any) => p.userId === userId && p.role === 'EDIT')

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, 'Access Denied')
  }

  const version = await context.entities.Version.findUnique({
    where: { id: versionId },
  })

  if (!version || version.documentId !== docId) {
    throw new HttpError(404, 'Version not found')
  }

  const updatedDoc = await context.entities.Document.update({
    where: { id: docId },
    data: {
      content: version.content,
    },
  })

  if (ioInstance) {
    const roomId = `document-${docId}`
    ioInstance.to(roomId).emit('documentEdit', { content: version.content })
  }

  return updatedDoc
}

export const shareDocument = async (
  args: { documentId: number; username: string; role: string },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id
  const docId = Number(args.documentId)

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  if (document.ownerId !== userId) {
    throw new HttpError(403, 'Access Denied')
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: args.username },
  })

  if (!targetUser) {
    throw new HttpError(404, 'User not found')
  }

  if (targetUser.id === userId) {
    throw new HttpError(400, 'Cannot share with yourself')
  }

  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId: docId,
        userId: targetUser.id,
      },
    },
    update: {
      role: args.role,
    },
    create: {
      documentId: docId,
      userId: targetUser.id,
      role: args.role,
    },
  })
}

export const revokePermission = async (args: { documentId: number, userId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const userId = context.user.id
  const docId = Number(args.documentId)
  const targetUserId = Number(args.userId)

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  if (document.ownerId !== userId) {
    throw new HttpError(403, 'Access Denied')
  }

  return context.entities.Permission.delete({
    where: {
      documentId_userId: {
        documentId: docId,
        userId: targetUserId,
      },
    },
  })
}

import { Server } from 'socket.io'

export let ioInstance: Server | null = null

export const webSocketFn = (io: Server, context: any) => {
  ioInstance = io

  io.on('connection', (socket) => {
    socket.on('joinDocument', async ({ documentId }) => {
      const roomId = `document-${documentId}`
      socket.join(roomId)
    })

    socket.on('documentEdit', async ({ documentId, content }) => {
      const roomId = `document-${documentId}`
      socket.to(roomId).emit('documentEdit', { content })
    })
  })
}

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { DocumentPage } from "./src/DocumentPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { userSignupFields } from "./src/auth" with { type: "ref" };
import { webSocketFn } from "./src/webSocket" with { type: "ref" };

import { getDocuments, getDocument, getPermissions } from "./src/queries" with { type: "ref" };
import { createDocument, updateDocumentContent, saveVersion, restoreVersion, shareDocument, revokePermission } from "./src/actions" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
    onAuthSucceededRedirectTo: "/",
  },
  webSocket: {
    fn: webSocketFn,
    autoConnect: true,
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("DocumentRoute", "/document/:id", page(DocumentPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),

    query(getDocuments, { entities: ["Document", "Permission"] }),
    query(getDocument, { entities: ["Document", "Permission", "Version", "User"] }),
    query(getPermissions, { entities: ["Permission", "User", "Document"] }),

    action(createDocument, { entities: ["Document"] }),
    action(updateDocumentContent, { entities: ["Document", "Permission"] }),
    action(saveVersion, { entities: ["Document", "Version", "Permission"] }),
    action(restoreVersion, { entities: ["Document", "Version", "Permission"] }),
    action(shareDocument, { entities: ["Document", "Permission", "User"] }),
    action(revokePermission, { entities: ["Permission", "Document"] }),
  ],
});

